function diff(old,n,path=""){
 if(JSON.stringify(old)===JSON.stringify(n))return [];
 if(old&&n&&typeof old==="object"&&typeof n==="object"&&Array.isArray(old)===Array.isArray(n)){
 const keys=new Set([...Object.keys(old),...Object.keys(n)]);
 return [...keys].flatMap(k=>diff(old[k],n[k],path+"/"+k));
 }
 return [{path,current:n,previous:old}];
}
